/// <summary>
/// N.Freidenberger 06.05.2025
/// </summary>
public void insert()
{
    WHSLicensePlate     locLicensePlate;
    WHSContainerType    containerType;

    if (this.ContainerTypeCode == '')
    {
        select firstonly crosscompany locLicensePlate
            where locLicensePlate.LicensePlateId == this.LicensePlateId
               && locLicensePlate.ContainerTypeCode != '';
        if (locLicensePlate.ContainerTypeCode)
        {
            select firstonly containerType
                where containerType.ContainerTypeCode == locLicensePlate.ContainerTypeCode;
            if (containerType.ContainerTypeCode)
            {
                this.ContainerTypeCode = locLicensePlate.ContainerTypeCode;
            }
        }
    }
    next insert();
}
